import{_ as a,o as t,c as l,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"2020-01-13 -- Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2020-01-13 -- Ceph Orchestration Meeting","date":"2020-01-13T00:00:00.000Z","updated":"2020-01-14T00:00:00.000Z","tags":["Ceph","Orchestrator","Distributed Storage","OSD Management","CephFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-01-13_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2020/2020-01-13_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780459816000}'),r={name:"posts/2020/2020-01-13_-_-_Ceph_Orchestration_Meeting.md"};function o(h,e,n,s,c,d){return t(),l("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph-orchestrator-会议" tabindex="-1">会议主题：Ceph Orchestrator 会议 <a class="header-anchor" href="#会议主题-ceph-orchestrator-会议" aria-label="Permalink to &quot;会议主题：Ceph Orchestrator 会议&quot;">​</a></h4><h4 id="日期-2020年1月13日" tabindex="-1">日期：2020年1月13日 <a class="header-anchor" href="#日期-2020年1月13日" aria-label="Permalink to &quot;日期：2020年1月13日&quot;">​</a></h4><h4 id="参会人员-具体人员名单" tabindex="-1">参会人员：[具体人员名单] <a class="header-anchor" href="#参会人员-具体人员名单" aria-label="Permalink to &quot;参会人员：[具体人员名单]&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>OSD 移除与替换</strong></p><ul><li>讨论了移除和替换 OSD 的流程，包括责任分配和排空操作。</li><li>提出了一个新的管理模块，用于处理 OSD 的排空操作，该模块可以被 Rook 和 Self ADM 直接消费，也可能被仪表盘独立使用。</li><li>讨论了排空 OSD 的具体步骤，如设置权重为零、等待 OSD 为空等。</li><li>提出了一个新的安全命令（safe command）来管理排空功能，并可能提供 API 供仪表盘或其他组件使用。</li></ul></li><li><p><strong>依赖问题与改进</strong></p><ul><li>讨论了 Promoter 依赖的 <code>exact-net</code> 库不再活跃开发的问题，以及可能的替代方案。</li><li>提出了改进 Safe ADM 的可执行文件结构，避免单一文件的复杂性，并建议使用 pip 安装。</li></ul></li><li><p><strong>日常运营与更新</strong></p><ul><li>讨论了取消每日 Orchestrator 站立会议，改为每周会议。</li><li>更新了关于 Rook 支持分区（partitions）和改进 OSD 发现机制的工作进展。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>开发一个新的管理模块来处理 OSD 排空操作，以简化流程并提高效率。</li><li>考虑替换 <code>exact-net</code> 库，以解决其不再活跃开发带来的问题。</li><li>改进 Safe ADM 的文件结构，使其更易于维护和管理。</li><li>取消每日 Orchestrator 站立会议，改为每周会议。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>开发新的管理模块，并确保其可以被 Rook 和 Self ADM 直接消费。</li><li>评估并替换 <code>exact-net</code> 库，以提高 Safe ADM 的稳定性和用户体验。</li><li>审查并合并关于改进 Safe ADM 文件结构的 Pull Request。</li><li>实施新的会议安排，取消每日站立会议，改为每周会议。</li></ul><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><ul><li>会议中提到的具体技术细节和代码实现需要进一步的技术讨论和开发工作。</li><li>所有决定和行动计划需要团队成员的协作和持续跟进。</li></ul><h4 id="下次会议" tabindex="-1">下次会议： <a class="header-anchor" href="#下次会议" aria-label="Permalink to &quot;下次会议：&quot;">​</a></h4><ul><li>日期：[具体日期]</li><li>时间：[具体时间]</li><li>地点：[具体地点或在线会议链接]</li></ul><p><strong>会议结束</strong></p>',15)])])}const p=a(r,[["render",o]]);export{_ as __pageData,p as default};
